      // ══════════════════════════════════════
      //  KEELING CURVE DATA (fixed, rounded historical teaching sample)
      //  1958 is an approximate starting level, not a complete annual mean.
      //  Source: NOAA Global Monitoring Laboratory
      // ══════════════════════════════════════
      // Keep the records on aligned, separate scales. The HTML legend and
      // data table provide the same information without relying on the canvas.
      var disposeKeelingChart=null;
      function attachKeelingChart(canvas){
        if(disposeKeelingChart){disposeKeelingChart();disposeKeelingChart=null;}
        if(!canvas)return;
        var active=true,observer=null,lastWidth=0,lastDpr=0;
        function paint(){
          if(!active)return;
          var width=Math.max(160,Math.round(canvas.offsetWidth||600)),height=448;
          var dpr=Number.isFinite(window.devicePixelRatio)&&window.devicePixelRatio>0?window.devicePixelRatio:1;
          if(width===lastWidth&&dpr===lastDpr)return;
          var c=canvas.getContext('2d');if (!c) return;
          lastWidth=width;lastDpr=dpr;
          canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);
          c.setTransform(dpr,0,0,dpr,0,0);
          c.fillStyle='#0f172a';c.fillRect(0,0,width,height);
          var left=46,right=12,plotWidth=width-left-right,plotHeight=128;
          var firstYear=KEELING_DATA[0].y,lastYear=KEELING_DATA[KEELING_DATA.length-1].y;
          function x(year){return left+(year-firstYear)/(lastYear-firstYear)*plotWidth;}
          function drawPlot(options){
            function y(value){return options.top+plotHeight-(value-options.min)/(options.max-options.min)*plotHeight;}
            c.fillStyle='#f1f5f9';c.font='bold 14px system-ui';c.textAlign='left';c.textBaseline='alphabetic';
            c.fillText(options.title,12,options.top-34);
            c.fillStyle='#cbd5e1';c.font='12px system-ui';c.fillText(options.subtitle,12,options.top-16);
            c.lineWidth=1;c.setLineDash([]);
            options.ticks.forEach(function(tick){
              var py=y(tick);c.strokeStyle='#64748b';c.beginPath();c.moveTo(left,py);c.lineTo(width-right,py);c.stroke();
              c.fillStyle='#e2e8f0';c.font='12px system-ui';c.textAlign='right';c.fillText(options.tickLabel(tick),left-8,py+4);
            });
            [firstYear,1990,lastYear].forEach(function(year){
              var px=x(year);c.strokeStyle='#64748b';c.beginPath();c.moveTo(px,options.top);c.lineTo(px,options.top+plotHeight);c.stroke();
              c.fillStyle='#e2e8f0';c.font='12px system-ui';c.textAlign=year===firstYear?'left':year===lastYear?'right':'center';
              c.fillText(String(year),px,options.top+plotHeight+22);
            });
            c.strokeStyle=options.color;c.lineWidth=2.5;c.setLineDash(options.dash);c.beginPath();
            options.data.forEach(function(point,index){var px=x(point.y),py=y(point[options.key]);if(index)c.lineTo(px,py);else c.moveTo(px,py);});
            c.stroke();c.setLineDash([]);c.fillStyle=options.color;
            options.data.forEach(function(point){
              var px=x(point.y),py=y(point[options.key]);
              if(options.square)c.fillRect(px-3,py-3,6,6);
              else{c.beginPath();c.arc(px,py,3,0,Math.PI*2);c.fill();}
            });
          }
          drawPlot({top:54,min:300,max:440,ticks:[300,350,400,440],tickLabel:function(value){return String(value);},title:t('stem.climateExplorer.keeling_chart_co2_title','Mauna Loa CO₂ (ppm)'),subtitle:t('stem.climateExplorer.keeling_chart_sample','Selected historical sample'),data:KEELING_DATA,key:'ppm',color:'#60a5fa',dash:[]});
          drawPlot({top:286,min:-0.2,max:1.4,ticks:[-0.2,0,0.5,1.0,1.4],tickLabel:function(value){return (value>0?'+':'')+value.toFixed(1);},title:t('stem.climateExplorer.keeling_chart_temperature_title','Temperature anomaly (°C)'),subtitle:t('stem.climateExplorer.keeling_chart_temperature_baseline','Baseline: 1951–1980'),data:GLOBAL_TEMP,key:'t',color:'#fbbf24',dash:[8,5],square:true});
        }
        paint();
        if(typeof ResizeObserver==='function'){observer=new ResizeObserver(paint);observer.observe(canvas);}
        else window.addEventListener('resize',paint);
        disposeKeelingChart=function(){active=false;if(observer)observer.disconnect();else window.removeEventListener('resize',paint);};
      }
      var KEELING_DATA = [
        { y: 1958, ppm: 315.0 }, { y: 1960, ppm: 316.9 }, { y: 1965, ppm: 320.0 },
        { y: 1970, ppm: 325.7 }, { y: 1975, ppm: 331.1 }, { y: 1980, ppm: 338.7 },
        { y: 1985, ppm: 346.1 }, { y: 1990, ppm: 354.4 }, { y: 1995, ppm: 360.9 },
        { y: 2000, ppm: 369.5 }, { y: 2005, ppm: 379.8 }, { y: 2010, ppm: 389.9 },
        { y: 2013, ppm: 396.5 }, { y: 2015, ppm: 401.0 }, { y: 2018, ppm: 408.5 },
        { y: 2020, ppm: 414.2 }, { y: 2022, ppm: 418.5 }, { y: 2024, ppm: 424.6 }
      ];
      // Global mean surface temperature anomaly (°C above the 1951-1980 average)
      // Source: NASA GISS GISTEMP v4
      var GLOBAL_TEMP = [
        { y: 1958, t: 0.07 }, { y: 1965, t: -0.10 }, { y: 1970, t: 0.04 },
        { y: 1975, t: 0.01 }, { y: 1980, t: 0.27 }, { y: 1985, t: 0.13 },
        { y: 1990, t: 0.46 }, { y: 1995, t: 0.46 }, { y: 2000, t: 0.42 },
        { y: 2005, t: 0.69 }, { y: 2010, t: 0.72 }, { y: 2015, t: 0.90 },
        { y: 2018, t: 0.85 }, { y: 2020, t: 1.01 }, { y: 2022, t: 0.89 },
        { y: 2023, t: 1.17 }, { y: 2024, t: 1.28 }
      ];
      var KEELING_MILESTONES = [
        { ppm:280,label:t('stem.climateExplorer.keeling_preindustrial_title','Approximate pre-industrial reference'),note:t('stem.climateExplorer.keeling_preindustrial_note','About 280 ppm before large-scale industrialization, reconstructed from ice cores. This reference is outside the plotted 1958–2024 record.') },
        { ppm:315,label:t('stem.climateExplorer.keeling_start_title','Mauna Loa measurements begin in 1958'),note:t('stem.climateExplorer.keeling_start_note','About 315 ppm is the starting level used here. Monitoring began during 1958, so this point is not a complete annual mean.') },
        { ppm:400,label:t('stem.climateExplorer.keeling_daily_title','A daily threshold crossed in May 2013'),note:t('stem.climateExplorer.keeling_daily_note','A daily Mauna Loa reading passed 400 ppm in 2013. Daily readings and annual averages differ: the sampled 2013 annual mean here is 396.5 ppm.') },
        { ppm:424.6,label:t('stem.climateExplorer.keeling_archive_title','2024 annual mean in this archive'),note:t('stem.climateExplorer.keeling_archive_note','This rounded historical value is the last CO₂ point in this activity. It is not today’s concentration. Source agencies publish newer observations and may revise past values.') }
      ];
      // Join by year, never by array index: the two source samples have gaps
      // in different years. A missing sample is not a zero or an interpolation.
      var keelingRows=KEELING_DATA.map(function(point){return {year:point.y,ppm:point.ppm,temp:null};});
      GLOBAL_TEMP.forEach(function(point){
        var row=keelingRows.find(function(value){return value.year===point.y;});
        if(row)row.temp=point.t;else keelingRows.push({year:point.y,ppm:null,temp:point.t});
      });
      keelingRows.sort(function(a,b){return a.year-b.year;});

